// This file is generated by AI.

// 语义高亮开关的回归护栏。
//
// WebGAL 脚本没有 Monarch tokenizer —— 编辑器里**全部颜色**都来自语言服务推的语义 token, 而这个
// 开关在 Monaco 里默认是 `'configuredByTheme'`, 两套内置主题的 `semanticHighlighting` 都是 false。
// 漏掉它的表现是"整篇纯文本", 没有任何报错: 类型检查、构建、单测全绿 (差异编辑器就这样漏过一次)。
//
// 因此这里直接读源码文本核对。这不是在测"常量等于自己"——它测的是**每个 WebGAL 编辑器宿主都
// 记得写这一行**, 而这件事只有源码能回答 (组件无法在 node 里渲染)。

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

const editorRoot = join(dirname(fileURLToPath(import.meta.url)), '..');

/** 承载 WebGAL 文本的 Monaco 编辑器宿主 (顺序无关)。 */
const HOSTS = ['src/ui/CodeEditor.svelte', 'src/ui/GitDiffEditor.svelte'];

const sourceOf = (file: string) => readFileSync(join(editorRoot, file), 'utf8');

describe('语义高亮开关', () => {
  for (const host of HOSTS) {
    it(`${host} 显式打开 semanticHighlighting`, () => {
      expect(sourceOf(host)).toContain(`'semanticHighlighting.enabled': true`);
    });
  }
});
